#include <iostream>
#include <string>

class BaseAccount {
public:
    BaseAccount(const std::string& owner, double balance)
        : owner_{owner}, balance_{balance >= 0.0 ? balance : 0.0} {
        std::cout << "[BaseAccount] Constructed: " << owner_ << "\n";
    }

    ~BaseAccount() {
        std::cout << "[BaseAccount] Destructed: " << owner_ << "\n";
    }

    double getBalance() const { return balance_; }

protected:
    void setBalance(double b) { balance_ = b; }

private:
    std::string owner_;
    double balance_{0.0};
};

class PremiumAccount : public BaseAccount {
public:
    // C++11 Inheriting constructors
    using BaseAccount::BaseAccount;

    // Custom derived constructor
    PremiumAccount(const std::string& owner, double balance, double cashbackRate)
        : BaseAccount(owner, balance), cashbackRate_{cashbackRate} {
        std::cout << "[PremiumAccount] Constructed with cashback: " << cashbackRate_ << "\n";
    }

    ~PremiumAccount() {
        std::cout << "[PremiumAccount] Destructed\n";
    }

    void applyCashback(double spent) {
        setBalance(getBalance() + spent * cashbackRate_);
    }

private:
    double cashbackRate_{0.01};
};

int main() {
    {
        std::cout << "--- Creating PremiumAccount ---\n";
        PremiumAccount acc("Alice", 500.0, 0.05);
        acc.applyCashback(100.0);
        std::cout << "Final Balance: " << acc.getBalance() << "\n";
        std::cout << "--- Exiting Scope ---\n";
    }
    return 0;
}

#include <iostream>
#include <iomanip>

class Account {
public:
    explicit Account(double initialBalance) {
        if (initialBalance >= 0.0) {
            balance_ = initialBalance;
        } else {
            balance_ = 0.0;
            std::cout << "Error: Initial balance was invalid.\n";
        }
    }

    void credit(double amount) {
        if (amount > 0.0) {
            balance_ += amount;
        }
    }

    bool debit(double amount) {
        if (amount > balance_) {
            std::cout << "Debit amount exceeded account balance.\n";
            return false;
        }
        balance_ -= amount;
        return true;
    }

    double getBalance() const { return balance_; }

private:
    double balance_{0.0};
};

class SavingsAccount : public Account {
public:
    SavingsAccount(double balance, double rate)
        : Account(balance), interestRate_{rate >= 0.0 ? rate : 0.0} {}

    double calculateInterest() const {
        return getBalance() * interestRate_;
    }

private:
    double interestRate_{0.0};
};

class CheckingAccount : public Account {
public:
    CheckingAccount(double balance, double fee)
        : Account(balance), transactionFee_{fee >= 0.0 ? fee : 0.0} {}

    void credit(double amount) {
        Account::credit(amount);
        Account::debit(transactionFee_);
    }

    bool debit(double amount) {
        bool success = Account::debit(amount);
        if (success) {
            Account::debit(transactionFee_);
        }
        return success;
    }

private:
    double transactionFee_{0.0};
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    SavingsAccount sav(1000.0, 0.05);
    double interest = sav.calculateInterest();
    std::cout << "Savings Interest: " << interest << "\n";
    sav.credit(interest);
    std::cout << "Savings Balance after interest: " << sav.getBalance() << "\n";

    CheckingAccount chk(200.0, 1.50);
    chk.credit(50.0); // +50, -1.50 fee = 248.50
    std::cout << "Checking Balance after credit: " << chk.getBalance() << "\n";

    chk.debit(300.0); // Exceeds balance, no fee charged
    std::cout << "Checking Balance after failed debit: " << chk.getBalance() << "\n";

    chk.debit(100.0); // -100, -1.50 fee = 147.00
    std::cout << "Checking Balance after successful debit: " << chk.getBalance() << "\n";

    return 0;
}
